mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM tb_customer_info
    WHERE customer_id = #{id}
      AND tenant_id = #{tenantId}
)

SELECT EXISTS (
    SELECT 1
    FROM tb_material_info
    WHERE material_id = #{id}
      AND tenant_id = #{tenantId}
)

SELECT COUNT(*)
FROM tb_sales_order_dt
WHERE sales_order_id = #{salesOrderId}
  AND tenant_id = #{tenantId}
  AND COALESCE(shipped_qty, 0) > 0

mapper.delete:
DELETE FROM tb_sales_order_dt
WHERE sales_order_id = #{salesOrderId}
  AND tenant_id = #{tenantId}
